# v104: „Hajóroncsok és ólomszennyezés” kártya (hu/en). Adat: wreck/calc.py -> wreck/data.json; ólom: McConnell et al. 2018 szövege
import json
D=json.load(open('wreck/data.json'));B=D['bins']
LD=json.load(open('lead/data.json'));BANDS=[(-125,-31),(-17,160),(165,193),(235,284)]
def _sp(x,y):
    def rk(v):
        o=sorted(range(len(v)),key=lambda i:v[i]);r=[0]*len(v)
        for k,i in enumerate(o): r[i]=k+1
        return r
    a,b=rk(x),rk(y);n=len(a);ma=sum(a)/n;mb=sum(b)/n
    return sum((p-ma)*(q-mb) for p,q in zip(a,b))/(sum((p-ma)**2 for p in a)*sum((q-mb)**2 for q in b))**.5
SP=_sp(D['all'],LD['b50'])
def cent(key,a):  # század összege: [a, a+100)
    return sum(v for b,v in zip(B,D[key]) if a<=b<a+100)
def build(l):
    H=l=='hu';T=lambda h,e:h if H else e
    fmt=(lambda n:f'{n:,}'.replace(',',' ')) if H else (lambda n:f'{n:,}')
    d1=lambda x:(f'{x:.1f}'.replace('.',',') if H else f'{x:.1f}')
    def yl(y):
        if H: return (f'Kr. e. {-y}' if y<0 else ('0' if y==0 else f'Kr. u. {y}'))
        return (f'{-y} BC' if y<0 else ('0' if y==0 else f'AD {y}'))
    def cl(a):
        n=abs(a)//100+(1 if a>=0 else 0)
        if H: return (f'Kr. e. {n}. század' if a<0 else f'Kr. u. {n}. század')
        o={1:'1st',2:'2nd',3:'3rd'}.get(n,f'{n}th');return (f'{o} century BC' if a<0 else f'{o} century AD')
    o=[]
    o.append('    <section class="card" id="shipcard">')
    o.append('      <h2>'+T('Hajóroncsok és ólomszennyezés','Shipwrecks and lead pollution')+'</h2>')
    o.append('      <p class="hint">'+T('A római gazdaság egészéről nincs statisztika, ezért a kutatás közvetett mércéket használ. Kettő közülük évszázadokon át követhető: a Földközi-tenger ismert hajóroncsainak száma a tengeri kereskedelemről, a grönlandi jégbe zárt ólom pedig az ezüstbányászatról és a pénzverésről árulkodik. Egyik sem Rómáról szól közvetlenül, de mindkettő azt a birodalmat méri, amely a várost ellátta.','There are no statistics for the Roman economy as a whole, so research relies on indirect measures. Two of them can be followed over centuries: the number of known shipwrecks in the Mediterranean tells of maritime trade, and the lead trapped in Greenland ice of silver mining and coinage. Neither is about Rome directly, but both measure the empire that supplied the city.')+'</p>')
    o.append('      <h3 class="aqh">'+T('Hajóroncsok ötvenévenként','Shipwrecks per fifty years')+'</h3>')
    # SVG
    Wd,Ht,L,R,Tp,Bt=860,300,46,12,14,40;pw=Wd-L-R;ph=Ht-Tp-Bt;ymax=200;bw=pw/len(B)
    s=['      <svg class="shipsvg" viewBox="0 0 %d %d" role="img" aria-label="%s">'%(Wd,Ht,T('Hajóroncsok száma ötvenévenként, Kr. e. 500-tól Kr. u. 700-ig','Number of shipwrecks per fifty years, 500 BC to AD 700'))]
    for y in (0,50,100,150,200):
        yy=Tp+ph-ph*y/ymax;s.append('<line class="gr" x1="%d" x2="%d" y1="%.1f" y2="%.1f"/><text class="ax" x="%d" y="%.1f" text-anchor="end">%d</text>'%(L,Wd-R,yy,yy,L-6,yy+4,y))
    for i,b in enumerate(B):
        x=L+i*bw;h1=ph*D['all'][i]/ymax;h2=ph*D['p100'][i]/ymax
        s.append('<rect class="b1" x="%.1f" y="%.1f" width="%.1f" height="%.1f"><title>%s–%s: %s / %s</title></rect>'%(x+1,Tp+ph-h1,bw-2,h1,yl(b),yl(b+50),d1(D['all'][i]),d1(D['p100'][i])))
        s.append('<rect class="b2" x="%.1f" y="%.1f" width="%.1f" height="%.1f"/>'%(x+bw*0.22,Tp+ph-h2,bw*0.56,h2))
    for y in range(-500,701,100):
        x=L+(y+500)/50*bw;s.append('<line class="tk" x1="%.1f" x2="%.1f" y1="%d" y2="%d"/>'%(x,x,Tp+ph,Tp+ph+5))
        if y%200==0: s.append('<text class="ax" x="%.1f" y="%d" text-anchor="middle">%s</text>'%(x,Tp+ph+22,yl(y)))
    s.append('</svg>');o.append(''.join(s))
    o.append('      <p class="hint aqleg"><span class="sw shb1"></span> '+T('minden keltezett roncs (%s) · '%fmt(D['n_all']),'all dated wrecks (%s) · '%fmt(D['n_all']))+'<span class="sw shb2"></span> '+T('csak a legfeljebb 100 éves pontossággal keltezettek (%s). Egy roncs a keltezési tartománya éveinek arányában oszlik el a sávok között, ezért a darabszámok törtek.'%fmt(D['n_p100']),'only those dated to within 100 years (%s). Each wreck is spread across the bars in proportion to the years of its date range, so the counts are fractional.'%fmt(D['n_p100']))+'</p>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('J. Strauss, A. I. Wilson, M. Flohr, <i>OxREP Shipwrecks Database</i>, 2.1 változat (2017), oxrep.web.ox.ac.uk/shipwrecks-database; %s roncs, ebből %s keltezett; saját számítás.'%(fmt(D['n']),fmt(D['dated'])),'J. Strauss, A. I. Wilson, M. Flohr, <i>OxREP Shipwrecks Database</i>, version 2.1 (2017), oxrep.web.ox.ac.uk/shipwrecks-database; %s wrecks, %s of them dated; own calculation.'%(fmt(D['n']),fmt(D['dated'])))+'</p>')
    c1b,c1,c2=cent('all',-100),cent('all',0),cent('all',100)
    o.append('      <p class="hint">'+T('A csúcs a Kr. u. 1. század: ekkorra %s roncs jut, a 2. századra már csak %s, kevesebb mint a fele. A szigorúbban keltezett roncsok ugyanezt mutatják, tehát az esés nem a pontatlan keltezések műterméke. A visszaesés már a 2. század első felében megkezdődik, vagyis évtizedekkel a 165-ben kitört Antoninus-féle járvány előtt.'%(fmt(round(c1)),fmt(round(c2))),'The peak is the 1st century AD: %s wrecks fall in it, but only %s in the 2nd century, less than half. The more strictly dated wrecks show the same, so the drop is not an artefact of imprecise dating. The decline begins already in the first half of the 2nd century, decades before the Antonine Plague broke out in 165.'%(fmt(round(c1)),fmt(round(c2))))+'</p>')
    o.append('      <p class="hint">'+T('<b>Mit nem jelent a görbe.</b> A roncsot a rakománya teszi láthatóvá és keltezhetővé: az amforát és a követ megtalálják a búvárok, a gabonát, a textilt vagy a fahordót nem. A hordó a császárkorban fokozatosan kiszorította az amforát, ezért a későbbi hajók egy része egyszerűen nem látszik. A legtöbb roncsot a francia és az olasz part sekély vizeiben találták, az észak-afrikai partot alig kutatták. Andrew Wilson, az adatbázis egyik szerzője ezért úgy ítéli, hogy a 2. századi esés valós mértéke bizonytalan: a szárazföldi kerámialeletek ekkor nem mutatnak visszaesést, a kereskedelem biztos összeomlása csak a 7–8. században következik be.','<b>What the curve does not mean.</b> A wreck is made visible and datable by its cargo: divers find amphorae and stone, but not grain, textiles or wooden barrels. During the imperial period the barrel gradually displaced the amphora, so some later ships simply do not show. Most wrecks were found in the shallow waters off the French and Italian coasts; the North African coast has hardly been surveyed. Andrew Wilson, one of the authors of the database, therefore judges the true scale of the 2nd-century drop to be uncertain: ceramic finds on land show no downturn at that time, and a certain collapse of trade comes only in the 7th–8th centuries.')+'</p>')
    o.append('      <h3 class="aqh">'+T('Kőrakományok és baeticai olaj','Stone cargoes and Baetican oil')+'</h3>')
    o.append('      <div class="regwrap"><table class="regtab shiptab">')
    o.append('        <thead><tr><th>'+T('Század','Century')+'</th><th>'+T('Összes roncs','All wrecks')+'</th><th>'+T('Kőrakomány (márvány, oszlop, tömb, szarkofág)','Stone cargo (marble, columns, blocks, sarcophagi)')+'</th><th>'+T('Dressel 20 amfora (baeticai olaj)','Dressel 20 amphorae (Baetican oil)')+'</th></tr></thead>')
    o.append('        <tbody>')
    for a in range(-200,500,100):
        o.append('          <tr><td>'+cl(a)+'</td><td>'+fmt(round(cent('all',a)))+'</td><td>'+d1(cent('stone',a))+'</td><td>'+d1(cent('d20a',a))+'</td></tr>')
    o.append('        </tbody>')
    o.append('        <tfoot><tr><td>'+T('Keltezett roncs összesen','Dated wrecks in total')+'</td><td>'+fmt(D['n_all'])+'</td><td>'+str(D['n_stone'])+'</td><td>'+str(D['n_d20'])+'</td></tr></tfoot>')
    o.append('      </table></div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('OxREP Shipwrecks Database 2.1 (2017); saját számítás. A Dressel 20 amforát szállító 22 roncsot egyenként átnéztem.','OxREP Shipwrecks Database 2.1 (2017); own calculation. The 22 wrecks carrying Dressel 20 amphorae were checked one by one.')+'</p>')
    o.append('      <p class="hint">'+T('A kőszállító hajók nem követik az általános görbét: a 3. században érik el a csúcsot (%s), amikor az összes roncs száma már jóval a tetőpont alatt van, és a 2. században sem esnek vissza. Wilson is a 2–3. századra teszi a kőszállítás tetőzését (vö. „Építkezések időrendben”).'%d1(cent('stone',200)),'Stone-carrying ships do not follow the general curve: they peak in the 3rd century (%s), when the total number of wrecks is already well below its maximum, and they do not decline in the 2nd century either. Wilson likewise places the peak of stone transport in the 2nd–3rd centuries (cf. “Building activity over time”).'%d1(cent('stone',200)))+'</p>')
    o.append('      <p class="hint">'+T('A Monte Testaccio olajamforáját, a Dressel 20-at 22 roncson azonosították: 15 a francia partoknál (ebből három Korzikánál), hat Itáliánál (kettő-kettő Szardíniánál és Szicíliánál, egy-egy Apuliánál és Toszkánánál), egy Hispaniánál. Több mint a felük a Kr. u. 1. századra esik, miközben a Testaccio keltezett feliratai a 2–3. századból valók (lásd „Róma élelmezése”): a két forrás tehát az olajkereskedelem két különböző szakaszát mutatja, nem ugyanazt.','The oil amphora of Monte Testaccio, the Dressel 20, has been identified on 22 wrecks: 15 off the French coasts (three of them off Corsica), six off Italy (two each off Sardinia and Sicily, one each off Apulia and Tuscany), one off Spain. More than half fall in the 1st century AD, whereas the dated inscriptions of the Testaccio come from the 2nd–3rd centuries (see “Feeding Rome”): so the two sources show two different phases of the oil trade, not the same one.')+'</p>')
    o.append('      <p class="hint">'+T('<b>Róma kikötőinél.</b> Az adatbázis Fiumicinónál, az ókori Portus területén 12 hajót tart számon (a legkorábbi hármat Kr. u. 42–66 közé, a legkésőbbieket a 4. századra keltezi), Ostiánál egyet, a Nemi-tóban négyet (Kr. u. 35–50). A part mentén Anziótól Civitavecchiáig további 11 roncs szerepel; közülük a Ladispoli B kilenc márványoszlopot szállított, a Ladispoli A-t pedig az adatbázis szerint nagy tárolóedények (<i>dolia</i>) szállítására alakíthatták ki. A koordináták az adatbázisban szándékosan pontatlanok, ezért a roncsok nincsenek a térképen.','<b>At the harbours of Rome.</b> The database records 12 ships at Fiumicino, the site of ancient Portus (dating the earliest three to AD 42–66 and the latest to the 4th century), one at Ostia, and four in Lake Nemi (AD 35–50). Along the coast from Anzio to Civitavecchia a further 11 wrecks are listed; of these Ladispoli B carried nine marble columns, and Ladispoli A, according to the database, may have been adapted to carry large storage jars (<i>dolia</i>). The coordinates in the database are deliberately imprecise, so the wrecks are not on the map.')+'</p>')
    o.append('      <h3 class="aqh">'+T('Ólom a grönlandi jégben','Lead in Greenland ice')+'</h3>')
    o.append('      <p class="hint">'+T('Az ezüstöt ólomtartalmú ércből nyerték ki, a kohók ólomfüstjét pedig a szél Grönlandig vitte, ahol évről évre a hóba rakódott. Egy 2018-as vizsgálat a jégmagból Kr. e. 1235 és Kr. u. 800 között évenkénti felbontásban becsülte meg az európai ólomkibocsátást. Mivel a dénár ezüstből készült, a görbe a bányászatot és a pénzverést követi.','Silver was extracted from lead-bearing ore, and the wind carried the lead fumes of the smelters as far as Greenland, where they settled in the snow year by year. A 2018 study estimated European lead emissions from the ice core at annual resolution between 1235 BC and AD 800. As the denarius was made of silver, the curve tracks mining and coinage.')+'</p>')
    S=LD['series'];X0,X1=-1100,800;Wd,Ht,L,R,Tp,Bt=860,300,46,12,22,40;pw=Wd-L-R;ph=Ht-Tp-Bt;ymax=2.5
    xx=lambda y:L+(y-X0)/(X1-X0)*pw;yy=lambda v:Tp+ph-ph*v/ymax
    s=['      <svg class="shipsvg" viewBox="0 0 %d %d" role="img" aria-label="%s">'%(Wd,Ht,T('Becsült európai ólomkibocsátás, Kr. e. 1100-tól Kr. u. 800-ig','Estimated European lead emissions, 1100 BC to AD 800'))]
    for k,(a0,b0) in zip('ABCD',BANDS): s.append('<rect class="bd" x="%.1f" y="%d" width="%.1f" height="%d"/><text class="ax bl" x="%.1f" y="%d" text-anchor="middle">%s</text>'%(xx(a0),Tp,xx(b0)-xx(a0),ph,(xx(a0)+xx(b0))/2,Tp-6,k))
    for v in (0,0.5,1,1.5,2,2.5): s.append('<line class="gr" x1="%d" x2="%d" y1="%.1f" y2="%.1f"/><text class="ax" x="%d" y="%.1f" text-anchor="end">%s</text>'%(L,Wd-R,yy(v),yy(v),L-6,yy(v)+5,d1(v)))
    s.append('<path class="ln" d="M'+' L'.join('%.1f %.1f'%(xx(y),yy(min(e,ymax))) for y,e in S if X0<=y<=X1)+'"/>')
    for y in range(-1000,801,100):
        s.append('<line class="tk" x1="%.1f" x2="%.1f" y1="%d" y2="%d"/>'%(xx(y),xx(y),Tp+ph,Tp+ph+5))
        if y%400==0: s.append('<text class="ax" x="%.1f" y="%d" text-anchor="%s">%s</text>'%(xx(y),Tp+ph+22,'end' if y==800 else 'middle',yl(y)))
    s.append('</svg>');o.append(''.join(s))
    o.append('      <p class="hint aqleg">'+T('Becsült ólomkibocsátás, ezer tonna évente (11 éves mozgó medián). A halvány sávok: <b>A</b> a köztársaság válsága (Kr. e. 125–31) · <b>B</b> a császárkori béke (Kr. e. 17 – Kr. u. 160) · <b>C</b> az Antoninus-féle járvány (165–193) · <b>D</b> a 3. századi válság (235–284).','Estimated lead emissions, thousand tonnes a year (11-year running median). The pale bands: <b>A</b> the crisis of the Republic (125–31 BC) · <b>B</b> the imperial peace (17 BC – AD 160) · <b>C</b> the Antonine Plague (165–193) · <b>D</b> the third-century crisis (235–284).')+'</p>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('J. R. McConnell, A. I. Wilson, A. Stohl és társai, „Lead pollution recorded in Greenland ice indicates European emissions tracked plagues, wars, and imperial expansion during antiquity”, <i>PNAS</i> 115 (2018) 5726–5731, Dataset S1 (a 3. ábra adatsora, %s év).'%fmt(LD['n']),'J. R. McConnell, A. I. Wilson, A. Stohl et al., “Lead pollution recorded in Greenland ice indicates European emissions tracked plagues, wars, and imperial expansion during antiquity”, <i>PNAS</i> 115 (2018) 5726–5731, Dataset S1 (the data series of Fig. 3, %s years).'%fmt(LD['n']))+'</p>')
    P=LD['per'];d2=lambda x:(f'{x:.2f}'.replace('.',',') if H else f'{x:.2f}')
    o.append('      <div class="regwrap"><table class="regtab aniotab shipltab">')
    o.append('        <thead><tr><th>'+T('Időszak','Period')+'</th><th>'+T('Átlag (ezer t/év)','Mean (thousand t/yr)')+'</th><th>'+T('Amihez a szerzők kötik','What the authors link it to')+'</th></tr></thead>')
    o.append('        <tbody>')
    R=[(T('Kr. e. 400–125','400–125 BC'),'-400_-125',T('karthágói, majd római bányászat Hispaniában','Carthaginian, then Roman mining in Spain')),
       (T('Kr. e. 125–31','125–31 BC'),'-125_-31',T('a köztársaság válsága: hispaniai háborúk, Sertorius, polgárháborúk; a mélypont Kr. e. 80–61 között %s'%d2(P['-80_-61'][0]),'the crisis of the Republic: wars in Spain, Sertorius, civil wars; the minimum, in 80–61 BC, is %s'%d2(P['-80_-61'][0]))),
       (T('Kr. e. 17 – Kr. u. 160','17 BC – AD 160'),'-17_160',T('a császárkori béke; új bányák Észak-Hispaniában, Germaniában, Galliában, Britanniában. A Kr. u. 1. század átlaga %s'%d2(P['1_100'][0]),'the imperial peace; new mines in northern Spain, Germany, Gaul, Britain. The mean of the 1st century AD is %s'%d2(P['1_100'][0]))),
       (T('Kr. u. 165–193','AD 165–193'),'165_193',T('az Antoninus-féle járvány: a magas szint vége','the Antonine Plague: end of the high level')),
       (T('Kr. u. 235–284','AD 235–284'),'235_284',T('a 3. századi válság és a Cyprianus-járvány (249–270); a dénár ezüsttartalma 4% alá esik','the third-century crisis and the Plague of Cyprian (249–270); the silver content of the denarius falls below 4%')),
       (T('Kr. u. 285–400','AD 285–400'),'285_400',T('a szint a járvány előttinek a töredéke marad','the level remains a fraction of that before the plague')),
       (T('Kr. u. 701–800','AD 701–800'),'701_800',T('kora középkori bányászat (Melle, Wirksworth): az első nagy emelkedés a járvány óta','early medieval mining (Melle, Wirksworth): the first major rise since the plague'))]
    for a_,k,c in R: o.append('          <tr><td>'+a_+'</td><td>'+d2(P[k][0])+'</td><td>'+c+'</td></tr>')
    o.append('        </tbody>')
    o.append('      </table></div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('az átlagok saját számítás a fenti adatsorból; a történeti megfeleltetés a szerzőké (McConnell és társai 2018).','the means are own calculations from the data series above; the historical links are the authors’ (McConnell et al. 2018).')+'</p>')
    o.append('      <p class="hint">'+T('A császárkori átlag (%s) másfélszerese a köztársaság válsága idején mértnek és közel háromszorosa a Kr. e. 80–61 közötti mélypontnak; a szerzők szerint a kibocsátás 64-ben, a dénár első rontásakor is hirtelen visszaesett. A 3. századi mélypont 260 körül 0,14 ezer tonna: ez a császárkor legalacsonyabb értéke, és arra az időszakra esik, amikor a birodalomban a legtöbb éremkincset rejtették el (250–275; lásd „Éremkincsek: mikor rejtettek el pénzt”). Kr. e. 900 után hasonlóan alacsony érték az adatsorban csak Kr. e. 356 és Kr. u. 489 körül fordul elő (0,12).'%d2(P['-17_160'][0]),'The imperial-period mean (%s) is one and a half times that of the crisis of the Republic and nearly three times the minimum of 80–61 BC; according to the authors, emissions also dropped suddenly in 64, at the first debasement of the denarius. The third-century minimum, around 260, is 0.14 thousand tonnes: the lowest value of the imperial period, and it falls in the period when most coin hoards were hidden in the empire (250–275; see “Coin hoards: when money was hidden”). After 900 BC similarly low values occur in the series only around 356 BC and AD 489 (0.12).'%d2(P['-17_160'][0]))+'</p>')
    o.append('      <p class="hint">'+T('A kibocsátás abszolút nagysága a szerzők szerint kétszeres szorzón belül bizonytalan; a változások iránya és időpontja megbízhatóbb, mint a tonnák. A két mérce a csúcsot egyformán a Kr. u. 1. századra teszi, a fordulatot viszont máskorra: a roncsok száma már a 2. század elején esik, az ólomé csak a 165-ös járvánnyal. Ötvenéves sávokban (Kr. e. 500 – Kr. u. 700) a két sor rangkorrelációja %s: együtt mozognak, de nem szorosan.'%d2(SP),'According to the authors the absolute size of the emissions is uncertain within a factor of two; the direction and timing of the changes are more reliable than the tonnes. The two measures agree in placing the peak in the 1st century AD, but put the turning point at different times: the number of wrecks falls already at the start of the 2nd century, that of lead only with the plague of 165. In fifty-year bands (500 BC – AD 700) the rank correlation of the two series is %s: they move together, but not closely.'%d2(SP))+'</p>')
    o.append('    </section>')
    return '\n'.join(o)+'\n'
SUB=('1 818 földközi-tengeri roncs ötvenévenként, kőrakományok, olajamforák; ólomkibocsátás a grönlandi jég alapján','1,818 Mediterranean wrecks per fifty years, stone cargoes, oil amphorae; lead emissions from Greenland ice')
